-- create "design_requests" table
CREATE TABLE "design_requests" ("id" uuid NOT NULL, "shop_id" bigint NOT NULL, "site" character varying(10) NOT NULL, "kind" character varying(10) NOT NULL, "status" character varying(20) NOT NULL DEFAULT 'drafting', "requested_by_user_id" bigint NOT NULL, "prompt_text" text NULL, "prompt_sha256" character(64) NOT NULL, "prompt_flags" jsonb NOT NULL, "base_sha" character(40) NOT NULL, "head_sha" character(40) NOT NULL, "candidate_sha" character(40) NULL, "published_sha" character(40) NULL, "branch" character varying(120) NOT NULL, "core_version" character varying(20) NOT NULL DEFAULT '', "design_floor_version" character varying(20) NOT NULL DEFAULT '', "diff_summary" jsonb NOT NULL, "guard" jsonb NULL, "preview_origin" character varying(255) NULL, "preview_registered_at" timestamptz NULL, "preview_expires_at" timestamptz NULL, "approved_by_user_id" bigint NULL, "approved_at" timestamptz NULL, "approved_head_sha" character(40) NULL, "approval_expires_at" timestamptz NULL, "publish_tag" character varying(60) NULL, "rejected_by_user_id" bigint NULL, "rejected_at" timestamptz NULL, "reject_reason" character varying(500) NULL, "change_note" character varying(500) NULL, "published_at" timestamptz NULL, "published_tag" character varying(60) NULL, "deployment_id" character varying(100) NULL, "restores_request_id" uuid NULL, "reverted_by_request_id" uuid NULL, "failure_code" character varying(40) NULL, "failure_detail" character varying(300) NULL, "rev" bigint NOT NULL DEFAULT 1, "idempotency_key" character varying(255) NULL, "idempotency_fingerprint" character(64) NULL, "claimed_by_credential_id" bigint NULL, "claimed_at" timestamptz NULL, "claim_expires_at" timestamptz NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "design_requests_kind_check" CHECK ((kind)::text = ANY ((ARRAY['change'::character varying, 'revert'::character varying])::text[])), CONSTRAINT "design_requests_site_check" CHECK ((site)::text = ANY ((ARRAY['storefront'::character varying, 'admin'::character varying])::text[])), CONSTRAINT "design_requests_status_check" CHECK ((status)::text = ANY ((ARRAY['drafting'::character varying, 'previewing'::character varying, 'awaiting_approval'::character varying, 'approved'::character varying, 'published'::character varying, 'rejected'::character varying, 'failed'::character varying, 'cancelled'::character varying, 'reverted'::character varying])::text[])));
-- create index "design_requests_idem_key" to table: "design_requests"
CREATE UNIQUE INDEX "design_requests_idem_key" ON "design_requests" ("shop_id", "idempotency_key") WHERE (idempotency_key IS NOT NULL);
-- create index "design_requests_one_active" to table: "design_requests"
CREATE UNIQUE INDEX "design_requests_one_active" ON "design_requests" ("shop_id", "site") WHERE ((status)::text = ANY ((ARRAY['drafting'::character varying, 'previewing'::character varying, 'awaiting_approval'::character varying, 'approved'::character varying])::text[]));
-- create index "design_requests_publish_tag_key" to table: "design_requests"
CREATE UNIQUE INDEX "design_requests_publish_tag_key" ON "design_requests" ("shop_id", "publish_tag") WHERE (publish_tag IS NOT NULL);
-- create index "design_requests_shop_id_id_key" to table: "design_requests"
CREATE UNIQUE INDEX "design_requests_shop_id_id_key" ON "design_requests" ("shop_id", "id");
-- create index "design_requests_shop_site_created" to table: "design_requests"
CREATE INDEX "design_requests_shop_site_created" ON "design_requests" ("shop_id", "site", "created_at");
-- create index "design_requests_status_updated" to table: "design_requests"
CREATE INDEX "design_requests_status_updated" ON "design_requests" ("status", "updated_at");
-- create "design_request_events" table
CREATE TABLE "design_request_events" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "shop_id" bigint NOT NULL, "request_id" uuid NOT NULL, "seq" bigint NOT NULL, "kind" character varying(30) NOT NULL, "from_status" character varying(20) NOT NULL DEFAULT '', "to_status" character varying(20) NOT NULL DEFAULT '', "actor_type" character varying(10) NOT NULL, "actor_user_id" bigint NULL, "actor_credential_id" bigint NULL, "head_sha" character varying(40) NOT NULL DEFAULT '', "detail" jsonb NOT NULL, "prev_hash" character(64) NOT NULL, "hash" character(64) NOT NULL, "created_at" timestamptz NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "design_request_events_actor_check" CHECK ((actor_type)::text = ANY ((ARRAY['service'::character varying, 'user'::character varying, 'system'::character varying])::text[])), CONSTRAINT "design_request_events_kind_check" CHECK ((kind)::text = ANY ((ARRAY['created'::character varying, 'claimed'::character varying, 'head_updated'::character varying, 'guard_run'::character varying, 'preview_registered'::character varying, 'screenshots_complete'::character varying, 'submitted'::character varying, 'changes_requested'::character varying, 'approved'::character varying, 'rejected'::character varying, 'cancelled'::character varying, 'guard_rechecked'::character varying, 'published'::character varying, 'failed'::character varying, 'revert_requested'::character varying, 'reverted_mark'::character varying, 'expired'::character varying])::text[])));
-- create index "design_request_events_request_seq_key" to table: "design_request_events"
CREATE UNIQUE INDEX "design_request_events_request_seq_key" ON "design_request_events" ("request_id", "seq");
-- create index "design_request_events_shop_created" to table: "design_request_events"
CREATE INDEX "design_request_events_shop_created" ON "design_request_events" ("shop_id", "created_at");
-- create "design_screenshots" table
CREATE TABLE "design_screenshots" ("id" uuid NOT NULL, "shop_id" bigint NOT NULL, "request_id" uuid NOT NULL, "phase" character varying(6) NOT NULL, "site" character varying(10) NOT NULL, "view_key" character varying(40) NOT NULL, "viewport" smallint NOT NULL, "role" character varying(10) NOT NULL, "attempt" smallint NOT NULL DEFAULT 1, "commit_sha" character(40) NOT NULL, "object_key" character varying(255) NOT NULL, "content_type" character varying(20) NOT NULL DEFAULT 'image/png', "byte_size" bigint NOT NULL, "width" bigint NOT NULL, "height" bigint NOT NULL, "sha256" character(64) NOT NULL, "diff_ppm" bigint NULL, "capture_manifest" jsonb NOT NULL, "purged_at" timestamptz NULL, "created_at" timestamptz NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "design_screenshots_height_check" CHECK ((height >= 1) AND (height <= 10000)), CONSTRAINT "design_screenshots_phase_check" CHECK ((phase)::text = ANY ((ARRAY['before'::character varying, 'after'::character varying])::text[])), CONSTRAINT "design_screenshots_role_check" CHECK ((role)::text = ANY ((ARRAY['owner'::character varying, 'staff'::character varying, 'anon'::character varying])::text[])), CONSTRAINT "design_screenshots_site_check" CHECK ((site)::text = ANY ((ARRAY['storefront'::character varying, 'admin'::character varying])::text[])), CONSTRAINT "design_screenshots_size_check" CHECK ((byte_size >= 1) AND (byte_size <= 2097152)), CONSTRAINT "design_screenshots_type_check" CHECK ((content_type)::text = 'image/png'::text), CONSTRAINT "design_screenshots_view_key_check" CHECK ((view_key)::text ~ '^[a-z0-9-]+$'::text), CONSTRAINT "design_screenshots_viewport_check" CHECK (viewport = ANY (ARRAY[390, 1280])), CONSTRAINT "design_screenshots_width_check" CHECK (width = viewport));
-- create index "design_screenshots_shop_created" to table: "design_screenshots"
CREATE INDEX "design_screenshots_shop_created" ON "design_screenshots" ("shop_id", "created_at");
-- create index "design_screenshots_slot_attempt_key" to table: "design_screenshots"
CREATE UNIQUE INDEX "design_screenshots_slot_attempt_key" ON "design_screenshots" ("request_id", "phase", "role", "viewport", "view_key", "attempt");
-- create "design_service_credentials" table
CREATE TABLE "design_service_credentials" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "shop_id" bigint NOT NULL, "name" character varying(100) NOT NULL, "key_prefix" character varying(12) NOT NULL, "key_hash" character(64) NOT NULL, "allowed_cidrs" jsonb NULL, "created_by_user_id" bigint NOT NULL, "created_at" timestamptz NOT NULL, "expires_at" timestamptz NOT NULL, "last_used_at" timestamptz NULL, "revoked_at" timestamptz NULL, PRIMARY KEY ("id"), CONSTRAINT "design_service_credentials_expiry_check" CHECK ((expires_at > created_at) AND (expires_at <= (created_at + '366 days'::interval))));
-- create index "design_service_credentials_key_hash_key" to table: "design_service_credentials"
CREATE UNIQUE INDEX "design_service_credentials_key_hash_key" ON "design_service_credentials" ("key_hash");
-- create index "design_service_credentials_shop" to table: "design_service_credentials"
CREATE INDEX "design_service_credentials_shop" ON "design_service_credentials" ("shop_id");
-- create "design_site_state" table
CREATE TABLE "design_site_state" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "shop_id" bigint NOT NULL, "site" character varying(10) NOT NULL, "current_request_id" uuid NULL, "current_tag" character varying(60) NOT NULL DEFAULT '', "current_sha" character varying(40) NOT NULL DEFAULT '', "core_version" character varying(20) NOT NULL DEFAULT '', "design_floor_version" character varying(20) NOT NULL DEFAULT '', "last_seen_main_sha" character varying(40) NOT NULL DEFAULT '', "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "design_site_state_site_check" CHECK ((site)::text = ANY ((ARRAY['storefront'::character varying, 'admin'::character varying])::text[])));
-- create index "design_site_state_shop_site_key" to table: "design_site_state"
CREATE UNIQUE INDEX "design_site_state_shop_site_key" ON "design_site_state" ("shop_id", "site");
-- create "design_untracked_changes" table
CREATE TABLE "design_untracked_changes" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "shop_id" bigint NOT NULL, "site" character varying(10) NOT NULL, "commit_sha" character(40) NOT NULL, "committed_at" timestamptz NOT NULL, "subject" character varying(200) NOT NULL DEFAULT '', "files_changed" bigint NOT NULL DEFAULT 0, "additions" bigint NOT NULL DEFAULT 0, "deletions" bigint NOT NULL DEFAULT 0, "detected_at" timestamptz NOT NULL, "acknowledged_by_user_id" bigint NULL, "acknowledged_at" timestamptz NULL, PRIMARY KEY ("id"), CONSTRAINT "design_untracked_changes_site_check" CHECK ((site)::text = ANY ((ARRAY['storefront'::character varying, 'admin'::character varying])::text[])));
-- create index "design_untracked_changes_commit_key" to table: "design_untracked_changes"
CREATE UNIQUE INDEX "design_untracked_changes_commit_key" ON "design_untracked_changes" ("shop_id", "site", "commit_sha");
-- hand-written: same-shop composite foreign keys, CHECK expressions atlas cannot see
ALTER TABLE "design_requests" ADD CONSTRAINT "design_requests_restores_fk" FOREIGN KEY ("shop_id", "restores_request_id") REFERENCES "design_requests" ("shop_id", "id") ON DELETE NO ACTION;
ALTER TABLE "design_requests" ADD CONSTRAINT "design_requests_reverted_by_fk" FOREIGN KEY ("shop_id", "reverted_by_request_id") REFERENCES "design_requests" ("shop_id", "id") ON DELETE NO ACTION;
ALTER TABLE "design_request_events" ADD CONSTRAINT "design_request_events_request_fk" FOREIGN KEY ("shop_id", "request_id") REFERENCES "design_requests" ("shop_id", "id") ON DELETE CASCADE;
ALTER TABLE "design_screenshots" ADD CONSTRAINT "design_screenshots_request_fk" FOREIGN KEY ("shop_id", "request_id") REFERENCES "design_requests" ("shop_id", "id") ON DELETE CASCADE;
ALTER TABLE "design_requests" ADD CONSTRAINT "design_requests_revert_link_check" CHECK ((kind = 'revert') = (restores_request_id IS NOT NULL));
ALTER TABLE "design_requests" ADD CONSTRAINT "design_requests_sha_check" CHECK (
  base_sha ~ '^[0-9a-f]{40}$' AND head_sha ~ '^[0-9a-f]{40}$'
  AND (candidate_sha IS NULL OR candidate_sha ~ '^[0-9a-f]{40}$')
  AND (published_sha IS NULL OR published_sha ~ '^[0-9a-f]{40}$')
  AND (approved_head_sha IS NULL OR approved_head_sha ~ '^[0-9a-f]{40}$')
  AND prompt_sha256 ~ '^[0-9a-f]{64}$');
ALTER TABLE "design_requests" ADD CONSTRAINT "design_requests_branch_check" CHECK (branch ~ '^ai/[a-z0-9][a-z0-9-]*/[0-9a-f-]{36}$');
ALTER TABLE "design_requests" ADD CONSTRAINT "design_requests_prompt_len_check" CHECK (prompt_text IS NULL OR char_length(prompt_text) <= 4000);
ALTER TABLE "design_requests" ADD CONSTRAINT "design_requests_preview_origin_check" CHECK (preview_origin IS NULL OR (preview_origin ~ '^https?://[^/?#[:space:]]+$'));
ALTER TABLE "design_requests" ADD CONSTRAINT "design_requests_diff_summary_size_check" CHECK (octet_length(diff_summary::text) <= 16384);
ALTER TABLE "design_request_events" ADD CONSTRAINT "design_request_events_detail_size_check" CHECK (octet_length(detail::text) <= 8192);
ALTER TABLE "design_request_events" ADD CONSTRAINT "design_request_events_hash_check" CHECK (hash ~ '^[0-9a-f]{64}$' AND prev_hash ~ '^[0-9a-f]{64}$' AND seq >= 1);
ALTER TABLE "design_screenshots" ADD CONSTRAINT "design_screenshots_manifest_size_check" CHECK (octet_length(capture_manifest::text) <= 2048);
